  internal static float HorizontalOrigin(Item item,NativeNotationContext page){return F((double)(Present(item.P(15))?item.P(15):item.P(7))*150+page.Prepared.X);}
  public static PrintedBarlinePlan Prepare(Item item,NativeNotationContext page,NativePageDocument doc,bool allowInitializedStaves=false){
   if(item.Code!=14||page==null||doc==null||item.P(4)<0||item.P(4)!=(int)item.P(4)||(item.P(12)!=0&&item.P(12)!=1))return null;int kind=(int)item.P(5);if(item.P(5)!=kind&&item.P(5)!=8.5f||(kind< -1||kind>2)&&(kind<8||kind>10))return null;for(int p=13;p<=20;p++)if(p!=15&&p!=17&&!(kind>=1&&kind<=2&&p==13)&&item.P(p)!=0)return null;if(Single.IsNaN(item.P(6))||Single.IsInfinity(item.P(6))||item.P(6)<short.MinValue||item.P(6)>short.MaxValue)return null;int span=Math.Max(1,(int)item.P(4)),high=page.Staff+span-1;if(high>(allowInitializedStaves?32:doc.MaximumDefinedStaff)||high>32)return null;if(kind!=9&&kind!=10&&item.P(8)!=0)return null;if((kind==9||kind==10)&&(Single.IsNaN(item.P(8))||Single.IsInfinity(item.P(8))||item.P(8)<short.MinValue||item.P(8)>short.MaxValue))return null;if(item.P(9)!=0)return null;
   float scale=page.Scale,x=HorizontalOrigin(item,page),bottom=doc.Tables.Vertical(page.Staff,Present(item.P(10))?item.P(10):kind==8||kind<=2?3:kind==9?1:7),top=doc.Tables.Vertical(high,Present(item.P(11))?item.P(11):kind==8||kind<=2?11:kind==9?13:7);var plan=new PrintedBarlinePlan{X=x,Bottom=bottom,Top=top,Scale=scale,Kind=kind};
