  }
  public static bool Draw(Graphics g,Item item,NativeNotationContext page,NativePageDocument doc,DrawingLibrary library){if(item.Code==14&&item.P(4)<=-1&&item.P(4)>=short.MinValue){RenderResourceAudit.Record("printed invisible bar","-1","original Code14 print branch","no painted geometry");return true;}var plan=Prepare(item,page,doc);if(plan==null)return false;var points=plan.Points;if(plan.Kind==8){Glyph glyph;if(library==null||!library.Symbols.TryGetValue(5,out glyph))return false;RenderResourceAudit.Record("printed brace","5:"+glyph.Name,glyph.Source,"recovered brace request and external vertices");float y=F((double)plan.Bottom-page.Scale*21);for(int n=0;n<glyph.Points.Length;n++)points.Add(new BarlinePoint(F((double)glyph.Points[n].X*page.Scale/4*plan.Horizontal+plan.X),F((double)glyph.Points[n].Y*page.Scale/4*plan.Vertical+y+page.Scale*21),glyph.Operations[n]));}else RenderResourceAudit.Record("printed bracket",plan.Kind.ToString(),"original Code14 routine","recovered explicit point commands");
   var state=g.Save();try{using(var matrix=page.Projection.Matrix())g.MultiplyTransform(matrix,MatrixOrder.Prepend);using(var path=new GraphicsPath(FillMode.Alternate))using(var pen=new Pen(Color.Black,NativePrintContext.DefaultLineWidth)){pen.LineJoin=LineJoin.Round;int kind=1;bool have=false;PointF previous=new PointF();Action flush=()=>{if(path.PointCount>0){if(kind!=1)g.TrackedFillPath(Brushes.Black,path);g.TrackedDrawPath(pen,path);var eps=NativeEpsExport.For(g);if(eps!=null)eps.ScorePath(path,kind!=1,NativePrintContext.DefaultLineWidth);}path.Reset();have=false;};foreach(var p in points){if(p.Operation>0){if(p.Operation!=3&&!(p.Operation==1&&kind==1))flush();path.StartFigure();have=false;kind=p.Operation==1?1:2;}var next=new PointF(NativeNotationContext.Word(p.X,true),NativeNotationContext.Word(p.Y,false));if(have)path.AddLine(previous,next);previous=next;have=true;}flush();}}finally{g.Restore(state);}return true;
  }
 }
